import React, { useEffect, useState } from "react";
import { Container, Table, Button, Modal, Form, Image } from "react-bootstrap";
import axios from "axios";
import AdminNavbar from "./AdminNavbar";

function Animals() {
  const [animals, setAnimals] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [alertVisible, setAlertVisible] = useState(false);

  const [formData, setFormData] = useState({
    nombre: "",
    especie: "Perro",
    descripcion: "",
    estado: "disponible",
    fotos: "",
  });

  const [editData, setEditData] = useState({
    id_animal: null,
    estado: "",
  });

  const token = localStorage.getItem("token");

  /* =========================
     CONSULTAR ANIMALES
  ========================= */
  const fetchAnimals = async () => {
    const res = await axios.get("http://localhost:5000/animals/", {
      headers: { Authorization: `Bearer ${token}` },
    });
    setAnimals(res.data);
  };

  useEffect(() => {
    fetchAnimals();
  }, []);

  /* =========================
     MODALES
  ========================= */
  const openModal = (animal = null) => {
    if (animal) {
      setEditData({ id_animal: animal.id_animal, estado: animal.estado });
      setShowEditModal(true);
    } else {
      setFormData({
        nombre: "",
        especie: "Perro",
        descripcion: "",
        estado: "disponible",
        fotos: "",
      });
      setShowModal(true);
    }
  };

  /* =========================
     CREAR
  ========================= */
  const handleSave = async () => {
    if (!formData.nombre || !formData.descripcion || !formData.fotos) {
      setAlertVisible(true);
      return;
    }

    await axios.post(
      "http://localhost:5000/animals/createAnimal",
      formData,
      { headers: { Authorization: `Bearer ${token}` } }
    );

    setShowModal(false);
    fetchAnimals();
  };

  /* =========================
     EDITAR ESTADO
  ========================= */
  const handleEditSave = async () => {
    await axios.put(
      `http://localhost:5000/animals/updateAnimal/${editData.id_animal}`,
      { estado: editData.estado },
      { headers: { Authorization: `Bearer ${token}` } }
    );

    setShowEditModal(false);
    fetchAnimals();
  };

  /* =========================
     ELIMINAR
  ========================= */
  const handleDelete = async (animal) => {
    if (animal.estado === "disponible") {
      alert("No se puede eliminar un animal disponible");
      return;
    }

    if (window.confirm(`¿Eliminar a ${animal.nombre}?`)) {
      await axios.delete(
        `http://localhost:5000/animals/deleteAnimal/${animal.id_animal}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchAnimals();
    }
  };

  return (
    <>
      <AdminNavbar />
      <Container className="mt-5">
        <div className="d-flex justify-content-between mb-3">
          <h1 style={{ color: "#2364c7", fontWeight: "bold" }}>Panel de Animales</h1>
          <Button variant="success" onClick={() => openModal()}>
            Agregar nuevo
          </Button>
        </div>

        <Table bordered hover responsive>
          <thead>
            <tr>
              <th>Imagen</th>
              <th>Nombre</th>
              <th>Especie</th>
              <th>Descripción</th>
              <th>Estado</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {animals.map((animal) => (
              <tr key={animal.id_animal}>
                <td>
                  <Image
                    src={`http://localhost:5000/uploads/${animal.fotos}`}
                    rounded
                    style={{ width: "120px" }}
                  />
                </td>
                <td>{animal.nombre}</td>
                <td>{animal.especie}</td>
                <td>{animal.descripcion}</td>
                <td>{animal.estado}</td>
                <td>
                  <Button size="sm" variant="info" className="me-2" onClick={() => openModal(animal)}>
                    Editar
                  </Button>
                  <Button size="sm" variant="danger" onClick={() => handleDelete(animal)}>
                    Eliminar
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>

        {/* MODAL CREAR */}
        <Modal show={showModal} onHide={() => setShowModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Agregar Animal</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            {alertVisible && <div className="alert alert-danger">Completa todos los campos</div>}
            <Form.Control
              className="mb-2"
              placeholder="Nombre"
              onChange={(e) => setFormData({ ...formData, nombre: e.target.value })}
            />
            <Form.Select
              className="mb-2"
              onChange={(e) => setFormData({ ...formData, especie: e.target.value })}
            >
              <option>Perro</option>
              <option>Gato</option>
            </Form.Select>
            <Form.Control
              as="textarea"
              rows={3}
              placeholder="Descripción"
              className="mb-2"
              onChange={(e) => setFormData({ ...formData, descripcion: e.target.value })}
            />
            <Form.Control
              placeholder="Nombre de la imagen (ej: tambo_perro.jpg)"
              onChange={(e) => setFormData({ ...formData, fotos: e.target.value })}
            />
          </Modal.Body>
          <Modal.Footer>
            <Button onClick={handleSave}>Guardar</Button>
          </Modal.Footer>
        </Modal>

        {/* MODAL EDITAR */}
        <Modal show={showEditModal} onHide={() => setShowEditModal(false)} centered>
          <Modal.Header closeButton>
            <Modal.Title>Editar Estado</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form.Select
              value={editData.estado}
              onChange={(e) => setEditData({ ...editData, estado: e.target.value })}
            >
              <option value="disponible">Disponible</option>
              <option value="adoptado">Adoptado</option>
              <option value="en_tratamiento">En tratamiento</option>
            </Form.Select>
          </Modal.Body>
          <Modal.Footer>
            <Button onClick={handleEditSave}>Guardar</Button>
          </Modal.Footer>
        </Modal>
      </Container>
    </>
  );
}

export default Animals;
